+    // ... even when the outputs that would follow are missing.
+    ext_no_inputs.resize(7);
+    BOOST_CHECK_EXCEPTION(deser_tx(ext_no_inputs, TX_WITH_WITNESS_P2P), std::ios_base::failure, HasReason("Transaction without inputs"));
