> [c655a69](https://github.com/bitcoin/bitcoin/pull/36521/changes/c655a696d8d1013bf61b815ba7b477840d31765c) _p2p: limit the weight of transactions and blocks while deserializing_:

Worth covering empty inputs and outputs through compact blocks and `blocktxn` responses too, since these decoders now inherit the stream parameters. The ordinary-parameter round trip can check that compatibility is preserved.

<details>
<summary>Extend the coverage</summary>

```diff
diff --git a/src/test/blockencodings_tests.cpp b/src/test/blockencodings_tests.cpp
index a951d2eba1..e07805e255 100644
--- a/src/test/blockencodings_tests.cpp
+++ b/src/test/blockencodings_tests.cpp
@@ -494,4 +494,30 @@ BOOST_AUTO_TEST_CASE(WeightLimitedDeserializationTest)
     check(block_txn, BlockTransactions{});
 }

+BOOST_AUTO_TEST_CASE(EmptyTransactionDeserializationTest)
+{
+    auto rand_ctx(FastRandomContext(uint256{42}));
+    CBlock block{BuildBlockTestCase(rand_ctx)};
+    for (const bool with_input : {false, true}) {
+        CMutableTransaction empty_tx;
+        if (with_input) empty_tx.vin.resize(1);
+        // A compact block prefills the first transaction of its block.
+        block.vtx[0] = MakeTransactionRef(empty_tx);
+        const CBlockHeaderAndShortTxIDs short_ids{block, rand_ctx.rand64()};
+        BlockTransactions block_txn;
+        block_txn.blockhash = block.GetHash();
+        block_txn.txn = block.vtx;
+
+        const auto check{[&](const auto& obj, auto deser) {
+            const auto data{DataStream{} << TX_WITH_WITNESS(obj)};
+            DataStream{data} >> TX_WITH_WITNESS(deser);
+            BOOST_CHECK_EQUAL((DataStream{} << TX_WITH_WITNESS(deser)).str(), data.str());
+            const auto reason = with_input ? "Transaction without outputs" : "Transaction without inputs";
+            BOOST_CHECK_EXCEPTION(DataStream{data} >> TX_WITH_WITNESS_P2P(deser), std::ios_base::failure, HasReason{reason});
+        }};
+        check(short_ids, CBlockHeaderAndShortTxIDs{});
+        check(block_txn, BlockTransactions{});
+    }
+}
+
 BOOST_AUTO_TEST_SUITE_END()
```

